&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Araign&#233;e goliath&lt;div style=&quot;float:right;&quot;&gt;FP 11&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Vermine&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Vermine.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;For&#234;t-Jungle&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/For&#234;t-Jungle.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 4 page 15&lt;/i&gt;
&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;12 800 PX&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Vermine.html&quot; title=&quot;Vermine&quot;&gt;Vermine&lt;/a&gt; de taille C, N&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init &lt;/b&gt;+1 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 18 m, &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Des-Vibrations-(Capacit&#233;).html&quot; title=&quot;Perception des vibrations&quot;&gt;perception des vibrations&lt;/a&gt; 18 m ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +4&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA&lt;/b&gt; 25, contact 3, pris au d&#233;pourvu 24 (Dex +1, naturelle +22, taille -8)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv&lt;/b&gt; 147 (14d8+84)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f &lt;/b&gt;+5, &lt;b&gt;Vig &lt;/b&gt;+15, &lt;b&gt;Vol &lt;/b&gt;+4&lt;/li&gt;&lt;li&gt;&lt;b&gt;Immunit&#233;s&lt;/b&gt; effets mentaux&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD&lt;/b&gt; 12 m, escalade 6 m&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +17 (6d8+22 et poison)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Espace&lt;/b&gt; 9 m ; &lt;b&gt;Allonge&lt;/b&gt; 9 m&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; poison, toile empoisonn&#233;e (+13 &#224; distance, DD 23, 14 pv), &lt;a class=&quot;pagelink&quot; href=&quot;Pi&#233;tinement.html&quot; title=&quot;Pi&#233;tinement&quot;&gt;pi&#233;tinement&lt;/a&gt; (4d8+22, DD 32)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Statistiques&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For&lt;/b&gt; 41, &lt;b&gt;Dex&lt;/b&gt; 13, &lt;b&gt;Con&lt;/b&gt; 22, &lt;b&gt;Int&lt;/b&gt; -, &lt;b&gt;Sag&lt;/b&gt; 10, &lt;b&gt;Cha&lt;/b&gt; 2&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA &lt;/b&gt;+10 ; &lt;b&gt;BMO &lt;/b&gt;+33 ; &lt;b&gt;DMD&lt;/b&gt; 44 (56 contre le croc-en-jambe)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; -7 (+1 en for&#234;t), &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +23, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +4 ;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Modificateurs raciaux&lt;/b&gt; +8 en &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;, +4 en &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;, +8 en &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; (+16 en for&#234;t)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;&#201;cologie&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Environnement&lt;/b&gt; for&#234;ts ou marais&lt;/li&gt;&lt;li&gt;&lt;b&gt;Organisation&lt;/b&gt; solitaire, couple ou colonie (3-6)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tr&#233;sor&lt;/b&gt; fortuit&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Pouvoirs sp&#233;ciaux&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Poison (Ext)&lt;/b&gt;. Morsure – blessure ; &lt;i&gt;JS&lt;/i&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 23 ; &lt;i&gt;fr&#233;quence&lt;/i&gt; 1/round pendant 6 rounds ; &lt;i&gt;effet&lt;/i&gt; affaiblissement temporaire 1d6 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;For&quot;&gt;For&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;paralysie&quot;&gt;paralysie&lt;/a&gt; 1 round ; &lt;i&gt;gu&#233;rison&lt;/i&gt; 2 JS cons&#233;cutifs.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Toile empoisonn&#233;e (Ext)&lt;/b&gt;. Ce pouvoir fonctionne comme le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Toile-(Capacit&#233;).html&quot; title=&quot;Toile&quot;&gt;toile&lt;/a&gt;, mais affecte toutes les cr&#233;atures situ&#233;es dans un rayonnement de 3 m&#232;tres de rayon. De plus, une cr&#233;ature touch&#233;e par la toile est &#233;galement affect&#233;e par le poison de l’araign&#233;e.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes d&#39;araign&#233;e&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Familier, &lt;a class=&quot;pagelink&quot; href=&quot;Araign&#233;e-&#201;carlate.html&quot; title=&quot;Araign&#233;e &#233;carlate&quot;&gt;Araign&#233;e &#233;carlate&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1/4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Araign&#233;e-G&#233;ante.html&quot; title=&quot;Araign&#233;e, Araign&#233;e g&#233;ante&quot;&gt;Araign&#233;e g&#233;ante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Araign&#233;e-Goliath.html&quot; title=&quot;Araign&#233;e, Araign&#233;e goliath&quot;&gt;Araign&#233;e goliath&lt;/a&gt;&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Araign&#233;e-Lunaire.html&quot; title=&quot;Araign&#233;e lunaire&quot;&gt;Araign&#233;e lunaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Araign&#233;e-Ogre.html&quot; title=&quot;Araign&#233;e, Araign&#233;e ogre&quot;&gt;Araign&#233;e ogre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Araign&#233;e-Crabe-G&#233;ante.html&quot; title=&quot;Araign&#233;e, Araign&#233;e-crabe g&#233;ante&quot;&gt;Araign&#233;e-crabe g&#233;ante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1/2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-Daraign&#233;es.html&quot; title=&quot;Araign&#233;e, Nu&#233;e d&amp;#39;araign&#233;es&quot;&gt;Nu&#233;e d&#39;araign&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tarentule-G&#233;ante.html&quot; title=&quot;Araign&#233;e, Tarentule g&#233;ante&quot;&gt;Tarentule g&#233;ante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veuve-Noire-G&#233;ante.html&quot; title=&quot;Araign&#233;e, Veuve noire g&#233;ante&quot;&gt;Veuve noire g&#233;ante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;i&gt;Cette gigantesque tarentule verte et brune dot&#233;e d’&#233;normes crocs ac&#233;r&#233;s est de la taille d’une grande maison.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les araign&#233;es goliath sont des chasseresses g&#233;antes qui se nourrissent le plus souvent de scorpions et de serpents g&#233;ants, ainsi que de jeunes dragons, mais elles attrapent parfois des proies plus petites qu’elles paralysent pour les d&#233;vorer plus tard. &lt;br /&gt;&lt;br /&gt;Gr&#226;ce au camouflage naturel dont elles disposent gr&#226;ce &#224; leurs poils et &#224; leur teinte, elles se cachent dans la canop&#233;e des for&#234;ts et tombent sur les cr&#233;atures peu m&#233;fiantes. Les femelles d&#233;vorent souvent leurs m&#226;les.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
